-- Postgres variant of 0965_dirimport.sql (issue #915). No foreign key beyond the tenant: the snapshot
-- names identities and groups by external id. rls.sql is regenerated by
-- `tessera admin gen-rls`.

-- +goose Up
CREATE TABLE dirimport_records (
  tenant_id TEXT NOT NULL REFERENCES tenants (id),
  system TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('people','entitlements')),
  rec_key TEXT NOT NULL,
  data TEXT NOT NULL,
  row_hash TEXT NOT NULL,
  imported_by TEXT NOT NULL,
  imported_at TEXT NOT NULL,
  PRIMARY KEY (tenant_id, system, kind, rec_key)
);
CREATE INDEX dirimport_records_key ON dirimport_records (tenant_id, kind, rec_key);
